def sp_low(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold().strip()

def sp_any(text,parts):
    for part in parts:
        if part in text:
            return True
    return False

def sp_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def sp_add(out,term,support_ids):
    support=sp_unique(support_ids)
    for row in out:
        if isinstance(row,dict) and row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def sp_has(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def sp_text(span):
    value=span.get('text','')
    if not isinstance(value,str):
        value=str(value)
    return value

def sp_support_text(row,by_id):
    parts=[]
    for uid in row.get('support_ids',[]):
        span=by_id.get(uid)
        if isinstance(span,dict):
            parts.append(sp_text(span))
    return ' '.join(parts)

def sp_false_old(row,by_id):
    if not isinstance(row,dict):
        return False
    term=row.get('term')
    if not isinstance(term,list) or not term or term[0]!='disposal_obligation':
        return False
    if not sp_has(term,'action_alternative') or not sp_has(term,'request_by'):
        return False
    text=sp_low(sp_support_text(row,by_id))
    return 'upon request or destroyed within' in text and sp_any(text,['termination of the project','expiration of the project','expiration or other termination of the project'])

def sp_exceptions(spans,start,limit):
    backup=''
    legal=''
    ids=[]
    stop=min(len(spans),start+limit+1)
    i=start+1
    while i<stop:
        raw=sp_text(spans[i])
        text=sp_low(raw)
        if not backup and sp_any(text,['back-up/archival','backup/archival','back-up or archival','backup or archival']):
            backup=raw
            ids.append(spans[i].get('id'))
        if not legal and 'single copy' in text and sp_any(text,['legal department','dispute resolution']):
            legal=raw
            ids.append(spans[i].get('id'))
        i+=1
    if backup and legal:
        return ['backup_archive_and_legal_record',backup,legal,sp_unique(ids)]
    if backup:
        return ['backup_archive',backup,'',sp_unique(ids)]
    if legal:
        return ['legal_dispute_record','',legal,sp_unique(ids)]
    return ['no_acquired_exception','','',[]]

def sp_emit_action(out,scope,action_id,kind,mode,material,trigger,timing,exception,raw,support):
    sp_add(out,['acq_disposal_action_v3',scope,action_id,kind,mode,material,trigger,timing,exception[0],exception[1],exception[2],raw],support+exception[3])

def sp_emit_linked(out,scope,raw,branch_raw,trigger,timing,support):
    exception=['no_acquired_exception','','',[]]
    rid=scope+':return'
    did=scope+':destroy'
    sp_emit_action(out,scope,rid,'return','linked','confidential_information_and_copies',trigger,timing,exception,raw,support)
    sp_emit_action(out,scope,did,'destroy','linked','confidential_information_and_copies',trigger,timing,exception,raw,support)
    sp_add(out,['acq_disposal_link_v3',scope,rid,did,'or',raw+' '+branch_raw],support)

def sp_emit_disclosure(out,scope,raw,support):
    text=sp_low(raw)
    need='required' if sp_any(text,['need to know','need-to-know','bona fide need']) else 'not_stated'
    extent='required' if sp_any(text,['involved in the performance','extent necessary','strictly necessary','disclosure is necessary']) else 'not_stated'
    confidentiality='written_required' if sp_any(text,['written agreement','bound in writing','agreed to be bound in writing']) else 'required' if sp_any(text,['bound by obligations','treat the confidential information','terms no less stringent']) else 'not_stated'
    roles=[]
    if sp_any(text,['employee','staff','personnel']):
        roles.append(['employee','receiving_party'])
    if 'consultant' in text:
        roles.append(['consultant','receiving_party'])
