    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node=byid[nid]
            for term in df_subterms(node.get('term')):
                out.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def df_owner_has(value,name):
    return df_has(value,name)

def df_role_tags(value,definitions):
    tags=set()
    todo=[value]
    expanded=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='representatives_of' and len(item)>1:
            key=str(item[1])
            if key not in expanded:
                expanded.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name in ('employees_of','internal_personnel_of') and len(item)>1:
            if not df_owner_has(item[1],'controlled_entities_of'):
                tags.add('employees')
            else:
                tags.add('controlled_employees')
        elif name=='source_recipient_class' and len(item)>2:
            roles=str(item[1])
            owner=str(item[2])
            if 'employees' in roles and owner in ('recipient_owned_all','recipient_and_controlled_same_roles'):
                tags.add('employees')
            if any(x in roles for x in ('contractors','consultants','advisers','professionals','agents','multiple')):
                tags.add('professionals')
        elif name in ('independent_contractors_of','consultants_of','agents_of','professional_advisors_of','legal_advisors_of','financial_advisors_of','accountants_of','lenders_of'):
            tags.add('professionals')
        elif name=='third_parties':
            tags.add('third_parties')
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def df_disclosure(task,entries):
    definitions=[]
    definition_roots=[]
    permissions=[]
    prohibitions=[]
    relevant=[]
    absence=[]
    for term,root in entries:
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
        elif term[0]=='complete_source_no_disclosure_permission':
            absence.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not df_has(action[1],'confidential_information'):
            continue
        relevant.append(root)
        tags=df_role_tags(action[2],definitions)
        if term[0]=='permission':
            permissions.append((root,tags,action[2]))
        else:
            prohibitions.append((root,tags,action[2]))
    for root,tags,recipient in permissions:
        if task=='nda-5' and 'employees' in tags:
            used=[root]
            if df_has(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':df_unique(used)}
        if task=='nda-7' and tags.intersection({'professionals','third_parties'}):
            used=[root]
            if df_has(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':df_unique(used)}
    for root,tags,recipient in prohibitions:
        if df_has(recipient,'outsiders_to'):
            continue
        if task=='nda-5' and 'employees' in tags:
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
        if task=='nda-7' and tags.intersection({'professionals','third_parties'}):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':df_unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def df_all_material_action(action):
    for item in df_subterms(action):
        if item[0]=='source_disposal_material' and len(item)>1 and item[1] in ('confidential_information_and_copies','information_copies_and_derivatives','all_source_stated_materials'):
            return True
        if item[0]=='information_bundle' and df_has(item,'confidential_information') and df_has(item,'copies_of'):
            return True
    return False

def decision_subterms(value):
    out = []
    todo = [value]
    while todo:
        item = todo.pop()
        if isinstance(item, list) and item:
            out.append(item)
            i = 1
            while i < len(item):
                if isinstance(item[i], list):
                    todo.append(item[i])
                i += 1
    return out

def decision_has(value, name):
    for item in decision_subterms(value):
        if item[0] == name:
            return True
    return False

def decision_unique(values):
    out = []
    for value in values:
        if value not in out:
            out.append(value)
    return out

def decision_entries(premises):
    nodes = premises.get('nodes', [])
    roots = premises.get('roots', [])
    by_id = {}
    for node in nodes:
        if isinstance(node, dict):
            by_id[node.get('id')] = node
    out = []
    for root in roots:
        todo = [root]
        seen = set()
        while todo:
            node_id = todo.pop()
            if node_id in seen or node_id not in by_id:
                continue
            seen.add(node_id)
            node = by_id[node_id]
            for term in decision_subterms(node.get('term')):
                out.append((term, root))
            for child in node.get('child_ids', []):
                todo.append(child)
    return out

def decision_role_tags(value, definitions):
    tags = set()
    todo = [value]
    expanded = set()
    while todo:
        item = todo.pop()
        if not isinstance(item, list) or not item:
            continue
        name = item[0]
        if name == 'representatives_of' and len(item) > 1:
            key = str(item[1])
            if key not in expanded:
                expanded.add(key)
                for owner, members in definitions:
                    if str(owner) == key or (isinstance(owner, list) and owner and owner[0] == 'party'):
                        todo.append(members)
            continue
        if name in ('employees_of', 'internal_personnel_of'):
            if len(item) > 1 and (decision_has(item[1], 'controlled_entities_of') or decision_has(item[1], 'affiliates_of')):
                tags.add('controlled_employees')
            else:
                tags.add('employees')
        elif name in ('independent_contractors_of', 'consultants_of', 'agents_of', 'professional_advisors_of', 'legal_advisors_of', 'financial_advisors_of', 'accountants_of', 'lenders_of'):
            tags.add('professionals')
        elif name == 'third_parties':
            tags.add('third_parties')
        i = 1
        while i < len(item):
            if isinstance(item[i], list):
                todo.append(item[i])
            i += 1
    return tags

def decision_full_material(value):
    for item in decision_subterms(value):
        if item[0] == 'source_stated_information':
            return True
        if item[0] == 'source_bounded_material' and len(item) > 1:
            base = item[1]
            if isinstance(base, list) and base and base[0] in ('confidential_information', 'information_bundle', 'source_stated_materials'):
                return True
        if item[0] == 'source_scoped_disposal_material' and len(item) > 1 and item[1] in ('confidential_information_and_copies', 'information_copies_and_derivatives', 'all_source_materials'):
            return True
        if item[0] == 'source_disposal_material' and len(item) > 1 and item[1] in ('confidential_information_and_copies', 'information_copies_and_derivatives', 'all_source_stated_materials'):
            return True
        if item[0] == 'information_bundle':
            return True
        if item[0] == 'confidential_information' and not decision_has(value, 'source_bounded_material'):
            return True
    return False
